$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
$out=$PSScriptRoot
$root=(Resolve-Path (Join-Path $out '../../..')).Path
function Data-Image($path){'data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes($path))}
$images=@{}
foreach($name in @('buried','armed','selected','ghost','ghost_invalid')){$images[$name]=Data-Image (Join-Path $out "icons/trap_bomb_$name.png")}
foreach($item in @{map='map_base_current_tiles.png';mock='mockup_free_placement.png';dust='effects/dig_map_4f.png';states='previews/trap_bomb_map_states_4x.png'}.GetEnumerator()){$images[$item.Key]=Data-Image (Join-Path $out $item.Value)}
foreach($item in @{old_map='Art/UI/Resources/TrapMap/trap_buried.png';old_1='Art/Battle/Resources/BattleArt/Props/trap_1.png';old_2='Art/Battle/Resources/BattleArt/Props/trap_2.png'}.GetEnumerator()){$images[$item.Key]=Data-Image (Join-Path $root "Game/Assets/_Project/$($item.Value)")}
$template=@'
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-094 · 함정 자유 설치</title>
<style>
:root{color-scheme:dark;font:16px/1.7 'Malgun Gothic',sans-serif;color:#e8e0cd;background:#0f1918}*{box-sizing:border-box}body{margin:0}main{max-width:1220px;margin:auto;padding:40px 24px 70px}header{border-top:2px solid #d5b16b;padding-top:24px}.eyebrow{color:#d5b16b;font-size:13px;letter-spacing:3px}h1{font-size:46px;line-height:1.2;margin:16px 0}h2{font-size:24px;line-height:1.4;margin:0 0 12px}h3{font-size:17px;margin:0 0 10px}p{margin:8px 0 18px}small,.muted{color:#acb6a7}.chips,.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.chip{padding:6px 12px;border:1px solid #4c594a;color:#dcc596;font-size:13px}section{margin-top:28px;padding:24px;background:#1a2925;border:1px solid #3c4c40}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{padding:20px;background:#121f1c;border:1px solid #35473a}.states{display:flex;flex-wrap:wrap;gap:16px}.state{text-align:center;min-width:110px}.checker{background-color:#303b31;background-image:linear-gradient(45deg,#485342 25%,transparent 25%),linear-gradient(-45deg,#485342 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#485342 75%),linear-gradient(-45deg,transparent 75%,#485342 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0}img,canvas{image-rendering:pixelated}img.icon{width:96px;height:96px;object-fit:contain;display:block;margin:10px auto}img.old{height:128px;width:auto;max-width:100%;object-fit:contain}.motion{width:128px;height:128px;margin:20px auto;display:block}.scroll{overflow:auto;border:1px solid #657055;margin-top:16px;max-height:640px}#map{display:block;cursor:crosshair;touch-action:none}button,select{font:inherit;background:#253a31;border:1px solid #a8996e;color:#f2e6c9;padding:8px 13px;cursor:pointer;min-height:44px}button:hover{background:#3e5440}button:focus-visible,select:focus-visible,input:focus-visible,canvas:focus-visible{outline:3px solid #f2cf8c;outline-offset:3px}input{accent-color:#d5b16b;vertical-align:middle}label{display:inline-flex;gap:8px;align-items:center}.status{min-height:28px;color:#ead18b}.mock{display:block;width:100%;max-width:768px;margin:auto}.legend{display:flex;gap:24px;flex-wrap:wrap;margin-top:12px}.dot{display:inline-block;width:10px;height:10px;margin-right:6px;background:#d5b16b}.red{background:#e16d61}.green{background:#9abe77}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px;border-bottom:1px solid #3c4c40;text-align:left}.note{border-left:3px solid #d5b16b;padding:10px 16px;background:#26372c}footer{margin-top:30px;font-size:13px;color:#acb6a7}@media(max-width:700px){main{padding:24px 12px}h1{font-size:34px}section{padding:16px}.columns{grid-template-columns:1fr}}
</style></head><body><main><header><div class="eyebrow">사람의 마지막 보루 / 그림 카드 K-094</div><h1>원하는 지점에 묻고,<br>폭발 범위를 읽는다.</h1><p>자유 배치용 함정 표식 · 한 화소 점선 · 작은 매설 먼지</p><div class="chips"><span class="chip">폭발 함정 1종</span><span class="chip">5m = 32화소</span><span class="chip">그림 검토용 · 게임 미연결</span></div></header>
<section><h2>01 / 지도 위 자유 배치</h2><p>포인터를 움직이면 함정과 폭발 범위가 따라옵니다. 빈 땅을 누르면 임시로 묻힙니다. 방향키로도 위치를 옮기고 Enter로 놓을 수 있습니다.</p><div class="controls"><label>폭발 반경 <input id="radius" type="range" min="5" max="20" step="0.5" value="10"><output id="meters">10m</output></label><label>검토 배율 <select id="zoom"><option value="1">1배</option><option value="2">2배 · 선은 한 화소</option></select></label><label>허용 색 <select id="color"><option value="brass">황동</option><option value="green">초록</option></select></label><label><input id="invalid" type="checkbox"> 불가 상태 강제 보기</label><button id="reset">처음 모습</button><button id="pause">먼지 멈추기</button></div><p id="status" class="status" role="status">그림을 읽고 있습니다.</p><div class="scroll"><canvas id="map" width="768" height="576" tabindex="0" aria-label="자유 배치 그림 체험 지도. 방향키 이동, 엔터 놓기."></canvas></div><div class="legend"><span><i class="dot"></i>놓을 수 있음</span><span><i class="dot green"></i>선택한 함정</span><span><i class="dot red"></i>놓을 수 없음 · ×</span></div><p class="note">현재 게임의 지도 타일로 재조합한 견본입니다. 지형 배치와 불가 판정은 그림 검토용 예시이며 실제 게임의 판정·구매·저장과 연결되지 않습니다. 범위 원이 겹친다는 이유로 설치 불가가 되지는 않습니다. 현재 정의의 폭발 피해 반경 기본값 10m를 처음 값으로 썼습니다.</p></section>
<section><h2>02 / 기존 그림과 새 지도 표식</h2><div class="columns"><div class="card"><h3>현재 게임에서 사용하는 그림</h3><div class="states"><div class="state"><img class="old checker" data-img="old_map" alt="기존 지도용 매설 함정"><p>지도 표식</p></div><div class="state"><img class="old checker" data-img="old_1" alt="기존 전투용 함정 첫 그림"><p>전투용 첫 그림</p></div><div class="state"><img class="old checker" data-img="old_2" alt="기존 전투용 함정 둘째 그림"><p>전투용 둘째 그림</p></div></div><small>두 전투 그림은 별도 함정 종류로 해석하지 않았습니다.</small></div><div class="card"><h3>새 표식 · 원본 24×24화소</h3><div class="states" id="states"></div><small>묻힌 흙과 금속 마개를 위에서 본 모습. 무장은 붉은 심지, 선택은 황동 모서리, 미리보기는 불투명도 45%로 구분합니다.</small></div></div></section>
<section><h2>03 / 묻을 때 피어나는 먼지</h2><div class="columns"><div class="card"><h3>4프레임 재생 · 0.4초 뒤 사라짐</h3><canvas id="dust" class="motion checker" width="128" height="128" aria-label="매설 먼지 네 프레임 반복 검토"></canvas><p style="text-align:center" id="frame">먼지 준비 중</p></div><div class="card"><h3>원본 크기와 기준점</h3><p>지도 효과는 32×32화소 네 장을 왼쪽부터 재생합니다. 매설 지점은 각 칸의 (16, 26)이며, 흙먼지는 위로 솟고 옅어집니다.</p><p>검토용 반복에는 쉬는 시간을 뒀습니다. 실제 사용은 한 번 재생 후 제거하는 그림입니다.</p><small>2배 지도에서도 범위 선은 한 화소로 다시 그립니다. 그림 파일 자체를 확대하면 선도 두꺼워지므로 임의 배율에는 다시 그리거나 비확대 선을 쓰는 벡터 원을 사용합니다.</small></div></div></section>
<section><h2>04 / 자유 배치 완성 견본</h2><p>칸 중앙을 벗어난 다섯 지점 · 반경 10m · 격자 표시 없음. 오른쪽 위 붉은 표시는 불가 상태 비교용입니다.</p><img class="mock" data-img="mock" alt="현재 지도 타일 위에 자유롭게 놓인 함정 다섯 개와 황동 초록 빨강 범위 원"></section>
<section><h2>05 / 전달 규격</h2><table><thead><tr><th>자료</th><th>규격</th><th>기준점</th></tr></thead><tbody><tr><td>지도 함정 5상태</td><td>각 24×24 · 가로 시트 120×24</td><td>중심 (12, 12)</td></tr><tr><td>매설 먼지</td><td>32×32 × 4장 · 초당 10장</td><td>매설점 (16, 26)</td></tr><tr><td>범위 원</td><td>반경 32 / 64 / 96 / 128 · 선 / 채움 / 합본</td><td>정중앙 · 바깥 여백 2화소</td></tr><tr><td>확대용 벡터 원</td><td>황동 / 초록 / 빨강 · 비확대 선 1화소</td><td>정중앙</td></tr><tr><td>공통 납품 시트</td><td>96×128 원본 / 288×384 최근접 3배</td><td>매설점 (48, 120) / (144, 360)</td></tr></tbody></table><p class="muted">지도 표식에는 사람의 발이 없습니다. 공통 시트의 기준선은 매설점으로 사용하며, 지도에서는 24화소 아이콘과 중심 기준점을 사용합니다. 새 파일명으로 전달하므로 기존 게임 시트의 장수·순서는 바꾸지 않았습니다.</p></section>
<footer>그림과 동작 견본은 이 파일에 모두 내장되어 서버 없이 열 수 있습니다. 원본·확대 보기·규격표·검증 기록은 Docs/References/codex_k094_v1/에 있습니다. Unity 실행·게임 연결·실제 게임 캡처는 수행하지 않았습니다.</footer></main>
<script>
const sources=__SOURCES__;
const el=id=>document.getElementById(id), images={}, labels={buried:'묻힘',armed:'무장',selected:'선택',ghost:'배치 미리보기',ghost_invalid:'불가 미리보기'};
let ready=false,zoom=1,hover={x:523,y:111},traps=[],effects=[],paused=false,start=performance.now(),errors=[];
function initial(){traps=[{x:307,y:114,state:'armed'},{x:451,y:177,state:'selected'},{x:569,y:284,state:'buried'},{x:184,y:371,state:'armed'}];effects=[];hover={x:523,y:111};}
function invalidAt(p){return el('invalid').checked||p.x<16||p.x>752||p.y<16||p.y>560||(p.x>=256&&p.x<=512&&p.y>=256&&p.y<=512);}
function radius(){return Math.round(Number(el('radius').value)*6.4*zoom);}
function ring(g,cx,cy,r,color){cx=Math.round(cx);cy=Math.round(cy);g.fillStyle=color;g.globalAlpha=.035;g.beginPath();g.arc(cx,cy,r,0,Math.PI*2);g.fill();g.globalAlpha=1;const grad=g.createRadialGradient(cx,cy,0,cx,cy,r);grad.addColorStop(0,color+'00');grad.addColorStop(1,color+'14');g.fillStyle=grad;g.beginPath();g.arc(cx,cy,r,0,Math.PI*2);g.fill();g.fillStyle=color;let x=r,y=0,err=1-r;while(x>=y){for(const [dx,dy] of [[x,y],[y,x],[-y,x],[-x,y],[-x,-y],[-y,-x],[y,-x],[x,-y]]){const arc=(Math.atan2(dy,dx)+Math.PI*2)*r;if(Math.floor(arc/4)%2===0)g.fillRect(cx+dx,cy+dy,1,1);}y++;if(err<0)err+=2*y+1;else{x--;err+=2*(y-x)+1;}}}
function icon(g,id,p){g.drawImage(images[id],Math.round((p.x-12)*zoom),Math.round((p.y-12)*zoom),24*zoom,24*zoom);}
function draw(now){if(!ready)return;const g=el('map').getContext('2d');g.imageSmoothingEnabled=false;g.clearRect(0,0,g.canvas.width,g.canvas.height);g.drawImage(images.map,0,0,768*zoom,576*zoom);for(const t of traps){ring(g,t.x*zoom,t.y*zoom,radius(),t.state==='selected'?'#9abe77':'#d5b16b');icon(g,t.state,t);}if(hover){const bad=invalidAt(hover);ring(g,hover.x*zoom,hover.y*zoom,radius(),bad?'#e16d61':el('color').value==='brass'?'#d5b16b':'#9abe77');icon(g,bad?'ghost_invalid':'ghost',hover);if(bad){g.fillStyle='#ffe0ce';const cx=Math.round(hover.x*zoom),cy=Math.round(hover.y*zoom);for(let k=-3;k<=3;k++){g.fillRect(cx+k,cy+k,1,1);g.fillRect(cx+k,cy-k,1,1);}}}
effects=effects.filter(e=>now-e.at<400);for(const e of effects){const f=Math.floor((now-e.at)/100);g.drawImage(images.dust,f*32,0,32,32,(e.x-16)*zoom,(e.y-26)*zoom,32*zoom,32*zoom);}
el('status').textContent=hover?(invalidAt(hover)?'× 놓을 수 없는 위치':'놓을 수 있음')+' · 지도 좌표 '+hover.x.toFixed(1)+', '+hover.y.toFixed(1)+'화소 · 폭발 반경 '+el('radius').value+'m · 임시 함정 '+traps.length+'개':'지도 위로 포인터를 옮겨 보세요.';
}
let dustTime=0,last=performance.now();function tick(now){const dt=now-last;last=now;if(!paused)dustTime+=dt;const phase=dustTime%1400,f=Math.floor(phase/100),g=el('dust').getContext('2d');g.clearRect(0,0,128,128);g.imageSmoothingEnabled=false;if(ready&&f<4){g.drawImage(images.dust,f*32,0,32,32,0,0,128,128);el('frame').textContent=(f+1)+' / 4 프레임';}else el('frame').textContent='다음 매설 기다림';draw(now);requestAnimationFrame(tick);}
function put(){if(!hover||invalidAt(hover))return;traps.push({...hover,state:'armed'});effects.push({...hover,at:performance.now()});}
el('map').onpointermove=e=>{const r=e.currentTarget.getBoundingClientRect();hover={x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom};};el('map').onpointerleave=()=>hover=null;el('map').onclick=put;
el('map').onkeydown=e=>{if(!hover)hover={x:523,y:111};const d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key];if(d){e.preventDefault();hover={x:Math.max(0,Math.min(768,hover.x+d[0])),y:Math.max(0,Math.min(576,hover.y+d[1]))};}if(e.key==='Enter'){e.preventDefault();put();}};
el('zoom').onchange=()=>{zoom=+el('zoom').value;el('map').width=768*zoom;el('map').height=576*zoom;};el('radius').oninput=()=>el('meters').value=el('radius').value+'m';el('reset').onclick=initial;el('pause').onclick=()=>{paused=!paused;el('pause').textContent=paused?'먼지 재생하기':'먼지 멈추기';};
Promise.all(Object.entries(sources).map(([id,src])=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{images[id]=img;resolve();};img.onerror=()=>reject(Error('그림 로드 실패: '+id));img.src=src;}))).then(()=>{for(const img of document.querySelectorAll('[data-img]'))img.src=sources[img.dataset.img];for(const [id,label] of Object.entries(labels)){const box=document.createElement('div');box.className='state';const img=new Image();img.className='icon checker';img.src=sources[id];img.alt=label;const text=document.createElement('div');text.textContent=label;box.append(img,text);el('states').append(box);}ready=true;initial();document.documentElement.dataset.qaImages=Object.keys(images).length;document.documentElement.dataset.qa='성공';
const test=document.createElement('canvas');test.width=265;test.height=265;const tg=test.getContext('2d');ring(tg,132,132,128,'#d5b16b');let edgeCount=0,crisp=true;const pixels=tg.getImageData(0,0,265,265).data;for(let y=0;y<265;y++)for(let x=0;x<265;x++){if(pixels[(y*265+x)*4+3]===255){edgeCount++;if(Math.abs(Math.hypot(x-132,y-132)-128)>.6)crisp=false;}}document.documentElement.dataset.qaRing=String(crisp&&edgeCount>200);draw(performance.now());}).catch(e=>{el('status').textContent=e.message;document.documentElement.dataset.qa='실패';});
window.addEventListener('error',e=>{errors.push(e.message);document.documentElement.dataset.qaErrors=errors.length;});document.documentElement.dataset.qaErrors=0;requestAnimationFrame(tick);
</script></body></html>
'@
$html=$template.Replace('__SOURCES__',($images|ConvertTo-Json -Compress))
$target=Join-Path $root '_HTML/6_그림_화면/codex_K-094_함정자유설치_v1.html'
[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))|Out-Null
[IO.File]::WriteAllText($target,$html,[Text.UTF8Encoding]::new($false))
Write-Output '검토 HTML 생성 완료'
